SELECT 'subscriptions' check_name,COUNT(*) violations FROM subscriptions s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN packages p ON p.id=s.package_id WHERE c.id IS NULL OR p.id IS NULL OR c.organization_id<>s.organization_id OR p.organization_id<>s.organization_id
UNION ALL SELECT 'invoices',COUNT(*) FROM invoices i LEFT JOIN customers c ON c.id=i.customer_id LEFT JOIN subscriptions s ON s.id=i.subscription_id WHERE c.id IS NULL OR c.organization_id<>i.organization_id OR (i.subscription_id IS NOT NULL AND (s.id IS NULL OR s.organization_id<>i.organization_id OR s.customer_id<>i.customer_id))
UNION ALL SELECT 'payments',COUNT(*) FROM payments p LEFT JOIN invoices i ON i.id=p.invoice_id LEFT JOIN customers c ON c.id=p.customer_id WHERE i.id IS NULL OR c.id IS NULL OR i.organization_id<>p.organization_id OR c.organization_id<>p.organization_id OR i.customer_id<>p.customer_id
UNION ALL SELECT 'pppoe_accounts',COUNT(*) FROM pppoe_accounts p LEFT JOIN customers c ON c.id=p.customer_id WHERE c.id IS NULL OR c.organization_id<>p.organization_id
UNION ALL SELECT 'support_tickets',COUNT(*) FROM support_tickets t LEFT JOIN customers c ON c.id=t.customer_id LEFT JOIN users u ON u.id=t.assigned_to WHERE (t.customer_id IS NOT NULL AND (c.id IS NULL OR c.organization_id<>t.organization_id)) OR (t.assigned_to IS NOT NULL AND (u.id IS NULL OR u.organization_id<>t.organization_id))
UNION ALL SELECT 'user_permissions',COUNT(*) FROM user_permissions p LEFT JOIN users u ON u.id=p.user_id LEFT JOIN users a ON a.id=p.updated_by WHERE u.id IS NULL OR u.organization_id<>p.organization_id OR (p.updated_by IS NOT NULL AND (a.id IS NULL OR a.organization_id<>p.organization_id))
UNION ALL SELECT 'onu_devices',COUNT(*) FROM onu_devices n LEFT JOIN customers c ON c.id=n.customer_id LEFT JOIN network_devices d ON d.id=n.olt_device_id WHERE (n.customer_id IS NOT NULL AND (c.id IS NULL OR c.organization_id<>n.organization_id)) OR (n.olt_device_id IS NOT NULL AND (d.id IS NULL OR d.organization_id<>n.organization_id))
UNION ALL SELECT 'refunds',COUNT(*) FROM refunds r LEFT JOIN payments p ON p.id=r.payment_id LEFT JOIN invoices i ON i.id=r.invoice_id LEFT JOIN customers c ON c.id=r.customer_id LEFT JOIN users u ON u.id=r.created_by WHERE p.id IS NULL OR i.id IS NULL OR c.id IS NULL OR u.id IS NULL OR p.organization_id<>r.organization_id OR i.organization_id<>r.organization_id OR c.organization_id<>r.organization_id OR p.invoice_id<>r.invoice_id OR p.customer_id<>r.customer_id OR i.customer_id<>r.customer_id OR u.organization_id<>r.organization_id;